/* sub_40D010: progress/tick callback. Walks the file-boundary table and
 * polls for user cancel (sets 42C9A0=6). Decode runs unattended: no-op.
 * The abort flag is only ever set here on cancel, so loops run to end. */
void d3uc_progress_callback(dec3w_ctx *c)
{
    (void)c;
}

/* sub_415F6C: per-stream decode driver (methods 22..35).
 * 42335C + 41BEF8 setup, then per block: top-ups 414290/414818,
 * 415FD4 match attempt (al==1) else 41680C fallback, 40D010 progress,
 * until 444EF8 >= 444EE4. Returns 444EF8. */
void d3uc_decode_stream(dec3w_ctx *c)
{
    unsigned int out_pos;
    d3uc_rc_init(c);
    d3uc_primer(c);
    do {
        out_pos = D3U_OUT_TOTAL_POS_32(&c->st, 0);
        if (out_pos >= D3U_PRIMER_TOTAL_32(&c->st, 0))
            d3uc_topup_dict_rebuild(c);
        out_pos = D3U_OUT_TOTAL_POS_32(&c->st, 0);
        if (out_pos >= D3U_TBL_444230_32(&c->st, 0))
            d3uc_topup_model_reinit(c);
        out_pos = d3uc_decode_match(c, 0U);
        if ((out_pos & 0xFFU) == 0U)
            d3uc_decode_fallback(c, 0U);
        d3uc_progress_callback(c);
        out_pos = D3U_OUT_TOTAL_POS_32(&c->st, 0);
    } while (out_pos < D3U_OUT_TOTAL_LEN_32(&c->st, 0));
}

int uharc_dec4uc_init(void **pctx, int method)
{
    dec3w_ctx *c;
    (void)method;
    c = (dec3w_ctx *)calloc(1, sizeof(*c));    if (!c)
        return 2;
    c->io_mem = (unsigned char *)calloc(1, (size_t)D3U_IO_SIZE);
    c->model_mem = (unsigned char *)calloc(1, (size_t)D3U_MODEL_SIZE);
    if (!c->io_mem || !c->model_mem) {
        free(c->io_mem); free(c->model_mem); free(c); return 2;
    }
    c->mem = NULL;
    /* Model blocks must live ABOVE the fixed DGROUP window (const slice
     * 0x428000-0x434CCC); bumping from 0x1000 paves over it (the dict
     * fill [0x1000,+0x800100) wipes consts/slots). Same fix as the 0.4
     * port: 0x600000 + ~28MB footprint < 64MB arena. Nonzero base also
     * keeps offset 0 as the alloc-fail NULL sentinel. */
    c->hi = 0x600000UL;
    {
        extern const unsigned char d3u_dgroup[];
        extern const unsigned long d3u_dgroup_base;
        extern const unsigned long d3u_dgroup_len;
        memcpy(d3u_ptr(c, d3u_dgroup_base), d3u_dgroup,
               (size_t)d3u_dgroup_len);
    }
    /* stream buffers: input 1MB at 0x3800000, staging 64KB at 0x3D00000 */
    c->in_buf = 0x03800000UL;
    c->out_buf = 0x03D00000UL;
    c->method = method;
    *pctx = c;
    return 0;
}

/* Header +9 bit6 selects the kennedy.xls PPM special case. */
static unsigned char g_dec4u_flags2;

void uharc_dec4uc_set_flags2(unsigned char flags2)
{
    g_dec4u_flags2 = flags2;
}

int uharc_dec4uc_decode_b(void *ctx,
                         const unsigned long *cum, unsigned long ncum,
                         uharc_dec_read_cb rcb, void *rctx,
                         uharc_dec_write_cb wcb, void *wctx,
                         unsigned long out_len)
{
    dec3w_ctx *c = (dec3w_ctx *)ctx;
    int method;
    (void)cum;
    (void)ncum;
    if (!c || !c->io_mem || !c->model_mem)
        return 1;
    method = c->method;
    c->rcb = rcb;
    c->rctx = rctx;
    c->wcb = wcb;
    c->wctx = wctx;
    c->err = 0;
    /* method comes from the container via init */
    if (d3uc_startup(c, 0U, (unsigned int)method) != 0)
        return 2;
    D3U_OUT_TOTAL_LEN_32(&c->st, 0) = (unsigned int)out_len;
    /* Container cumulative file-end table (dword_44422C). The table lives
     * in the arena as 32-bit entries (the original was a malloc'ed int[]),
     * with one extra zero terminator entry. The top-up walker in
     * d3uc_topup_model_reinit consults it via dword_44422C; without it (cell 0) the
     * decoder takes the B7D fallback (EE4 threshold), top-up maintenance
     * never runs, models drift, and decode dies late with SIGFPE.
     * Same pattern as the 0.4 port's A_PROG staging. */
    if (cum && ncum) {
        unsigned long i;
        unsigned long base = c->hi;
        c->hi = base + 4UL * (ncum + 1UL);
        for (i = 0; i < ncum; i++)
            d3u_st32(c, (unsigned long)(base + 4UL * i), (unsigned int)cum[i]);
        d3u_st32(c, (unsigned long)(base + 4UL * ncum), 0U);
        D3U_CUM_TABLE_PTR_32(&c->st, 0) = (unsigned int)base;
        /* asm 0x414025..0x414062 (sub_413838 tail): when byte_428ED9
         * (header +9 bit6) is set, scan for a 0xFB670 file. */
        if (g_dec4u_flags2 & 0x40) {
            unsigned prev = 0;
            for (i = 0; i < ncum; i++) {
                unsigned e = (unsigned)cum[i];
                if (e - prev == 0xFB670U) break;
                prev = e;
            }
            D3U_TBL_444228_32(&c->st, 0) = prev;
            D3U_FLAG_444EA2_8(&c->st, 0) = (unsigned char)((prev == 0) ? 10 : 0);
        }
    } else {
        D3U_CUM_TABLE_PTR_32(&c->st, 0) = 0U;
    }
    D3U_IN_BUFFER_BASE_32(&c->st, 0) = (unsigned int)c->in_buf;
    D3U_OUT_BUFFER_BASE_32(&c->st, 0) = (unsigned int)c->out_buf;
    D3U_OUT_FLUSH_THRESH_32(&c->st, 0) = 0xFF00UL;
    D3U_TBL_444EFC_32(&c->st, 0) = 0x40000UL;
    D3U_IN_AVAIL_32(&c->st, 0) = 0;
    D3U_IN_POS_32(&c->st, 0) = 0;
    D3U_IN_ABS_POS_32(&c->st, 0) = 0;
    D3U_STATUS_ERR_32(&c->st, 0) = 0;
    D3U_OUT_STAGED_LEN_32(&c->st, 0) = 0;
    D3U_OUT_TOTAL_POS_32(&c->st, 0) = 0;
    d3uc_decode_stream(c);
    if (D3U_OUT_STAGED_LEN_32(&c->st, 0) != 0)
        d3uc_flush_out(c);
    if (c->err)
        return c->err;
    if ((unsigned long)D3U_STATUS_ERR_32(&c->st, 0) != 0)
        return 4;
    if (D3U_OUT_TOTAL_POS_32(&c->st, 0) != (unsigned int)out_len)
        return 4;
    return 0;
}

void uharc_dec4uc_free(void *ctx)
{
    dec3w_ctx *c = (dec3w_ctx *)ctx;
    if (!c)
        return;
    free(c->io_mem);
    free(c->model_mem);
    free(c);
}

